INSERT INTO ontology_nodes (node_id, type, label, props) VALUES ('PROJECT:1', 'PROJECT', '극한업무', '{"source": {"project_id": "PRJ-LASTDAY", "title": "극한업무", "schema_version": "3.0-notion", "timezone": "Asia/Seoul", "original_date": "2026-10-23", "planning_dates": ["2026-10-23", "2026-10-24", "2026-10-25"], "unit_count": 1, "meal_min": [720, 780], "latest_wrap_min": 1080, "initial_prep_min": 60, "wrap_min": 30, "crew_start_min": 480, "max_continuous_duty_min": 300, "actor_prep_min": 45, "ready_buffer_min": 5, "default_change_budget_cap_krw": 600000, "budget_definition": "원본 당일 장소·장비비는 선지급되어0원. 새 장소·장비·협의비와 미선지급 이동비를 합산한 한도이며 제작 전체 예산이 아님.", "is_synthetic": true, "scene_group_rule": "야외2씬은 같은 후보 장소, 실내4씬은 같은 후보 장소를 사용한다. 복합 장소는 두 그룹 모두 배정 가능.", "solver_boundary": "한 날짜에 24씬 전체 촬영. 4씬씩 6묶음의 내부 순서·연속 촬영을 고정한다. 다일 분할·촬영 삭제·대역 교체는 제외.", "planning_scope": "one shooting day per proposal; six contiguous planning units / 24 scenes", "episode_id": "EP-01", "legal_effective_date": "2026-10-23"}, "adapterScope": "fixed AM; replan PM only", "notSupported": ["whole-day reordering", "full V3 cost/score/approval semantics", "external fourth location", "safety stop workflow"]}') ON CONFLICT DO NOTHING;
